def resources():
    payload = gzip.decompress(base64.b64decode(BUNDLE)).decode('ascii')
    value = strict_json(payload, max_text=2_000_000)
    # The README carries the current experiment protocol.
    value.pop('experiments.md', None)
    return {name: content.encode('latin1') for name, content in value.items()}

def materialize(root, *, run=False):
    root = Path(root).resolve()
    missing, preserved = [], []
    values = resources()
    for name, payload in values.items():
        path = relative(root, name)
        if path.exists():
            if not path.is_file():
                raise ValueError('Runtime resource target must be a regular file: '+name)
            preserved.append(name)
        else:
            missing.append((name, path, payload))
    refresh = None
    receipt = relative(root, RECEIPT)
    if RECEIPT in values and receipt.is_file():
        before = receipt.read_bytes()
        if before != values[RECEIPT] and sha256(before.replace(b'\r\n', b'\n')).hexdigest() in PREVIOUS:
            expected = strict_json(values[RECEIPT].decode('utf-8'))
            pending = {path: payload for _, path, payload in missing}
            verify(receipt.parent, expected, expected.get('upstream_commit'), pending=pending)
            refresh = (receipt, before, values[RECEIPT])
            preserved.remove(RECEIPT)
    if run:
        for _, path, payload in missing:
            publish(path, payload)
        if refresh:
            replace(*refresh)
    return dict(format='evocond_runtime_resources_v1', root=str(root), run=run,
        missing=[name for name, _, _ in missing], preserved=preserved, created=len(missing) if run else 0,
        refresh=[RECEIPT] if refresh else [], updated=int(run and refresh is not None))

def replace(path, before, payload):
    descriptor, name = tempfile.mkstemp(prefix='.evocond-', suffix='.tmp', dir=path.parent)
    temporary = Path(name)
    try:
        with os.fdopen(descriptor, 'wb') as stream:
            stream.write(payload)
            stream.flush()
            os.fsync(stream.fileno())
        # Replace only the known receipt inspected before publication.
        if path.read_bytes() != before:
            raise ValueError('Source receipt changed during resource preparation')
        os.replace(temporary, path)
    finally:
        temporary.unlink(missing_ok=True)

def verify(root, value, pin, *, pending=None):
    if (not isinstance(value, dict) or value.get('format') != 'evocond_vendored_source_v1'
            or not isinstance(pin, str) or not pin or value.get('upstream_commit') != pin
            or not isinstance(value.get('files'), dict) or not value['files']):
        raise ValueError('Vendored source provenance differs from the reviewed baseline')
    # Verify shipped source independently of the outer Git repository.
    for name, digest in value['files'].items():
        path = relative(root, name)
        if path.is_file():
            payload = path.read_bytes()
        elif pending is not None and path in pending:
            payload = pending[path]
        else:
            raise ValueError('Missing vendored source: '+name)
        if sha256(payload).hexdigest() != digest and sha256(payload.replace(b'\r\n', b'\n')).hexdigest() != digest:
            raise ValueError('Vendored source changed: '+name)
    return pin

def reviewed(root, pin):
    root = Path(root).resolve()
    receipt = root/'source.json'
    if not receipt.is_file():
        version = subprocess.check_output(['git', '-c', f'safe.directory={root.as_posix()}', '-C', str(root), 'rev-parse', 'HEAD'], text=True).strip()
        if version != pin:
            raise ValueError('Official checkout must use the reviewed pinned commit')
        return version
    value = json.loads(receipt.read_text(encoding='utf-8'))
    return verify(root, value, pin)

def main():
    parser = argparse.ArgumentParser(description='Restore pinned runtime settings without downloading models or data.')
    parser.add_argument('--root', type=Path, default=Path('.'))
    parser.add_argument('--run', action='store_true')
    args = parser.parse_args()
    print(json.dumps(materialize(args.root, run=args.run), ensure_ascii=True))

if __name__ == '__main__':
    main()

